  "primary_collocate": "在庫切れ",
  "collocation_distractors": [
    {
      "word": "在庫終わり",
      "explanation": "「終了」の意で「終わり」を複合名詞として直接後置するのは不自然であり、慣用的に「在庫切れ」を用いる。"
    },
    {
      "word": "在庫消滅",
      "explanation": "「消滅」は自然現象や権利・痕跡などが失われる際に用いる語であり、商品の品切れを表す複合語としては成立しない。"
    },
    {
      "word": "在庫空っぽ",
      "explanation": "「空っぽ」は口語の俗称的形容表現であり、「在庫」と結合した複合語としては定着しておらず不自然。"
    }
  ],
  "collocation_wrong_collocate": "在庫落ち",
  "cloze_distractors": [
    {
      "word": "遺産",
      "explanation": "「遺産」は前世代から受け継いだ財産や歴史的遺物を指す語であり、店舗や流通で扱う商品を指す文脈には適さない。"
    },
    {
      "word": "預金",
      "explanation": "「預金」は銀行口座等に預け入れた金銭を指す語であり、商品の手持ち量を表す文脈では意味が通らない。"
    },
    {
      "word": "余白",
      "explanation": "「余白」は紙面などの空いている部分を指す語であり、保管されている物品を指す文脈には全く合致しない。"
    }
  ],
  "discrimination_wrong_sentences": [
